/* spektrafilm-mode film/paper/colorimetry data for src/iop/filmemulation.c --
 * a straight port of every film and print-paper profile bundled with the
 * spektrafilm project (https://github.com/andreavolpato/spektrafilm,
 * CC BY-SA 4.0, by Andrea Volpato -- see that project's
 * SPEKTRAFILM_LICENSE.txt for the full attribution/redistribution terms),
 * plus the shared CIE colorimetry and illuminant spectra its algorithm
 * needs. Generated by a one-off script (gen_spektrafilm_data.py, not
 * checked in -- see task notes) that reads spektrafilm's own profile JSON
 * files, replicating its own data-prep math (Hanatos2025
 * per-stock sensitivity window, CAT16 adaptation to each stock's reference
 * illuminant, DIR-coupler matrix resolution, NaN-masked spectral edges)
 * so the baked tables can be consumed directly by simple per-pixel math in
 * filmemulation.c. Treat this file as data, not something to hand-edit;
 * regenerate it if spektrafilm's own profile data changes.
 *
 * #include'd directly into filmemulation.c (not separately compiled),
 * following the same convention as external/filmemulation_data.c.
 */

#define SF_N_WAVELENGTHS 81
#define SF_N_LOG_EXPOSURE 256
#define SF_N_FILMS 20
#define SF_N_PAPERS 8

typedef struct dt_sf_film_t
{
  const char *stock;
  const char *display_name;
  gboolean positive;
  int default_paper; // index into dt_sf_papers, from this stock's target_print
  int viewing_illuminant; // index into sf_view_illuminants -- for positive/reversal stocks viewed directly (no paper stage)
  const float (*sensitivity)[3]; // [SF_N_WAVELENGTHS][3], 10^log_sensitivity, hanatos2025 window folded in
  float cat16_matrix[3][3]; // XYZ (adapted to this stock's reference illuminant) = M @ linear AdobeRGB
  float surface_poly[3][14]; // hanatos2025 adaptation surface (degree-4 poly), optional
  float tc_center[2]; // tri2quad(reference illuminant xy) -- surface poly evaluation center
  const float (*density_curves)[3]; // [SF_N_LOG_EXPOSURE][3], H&D curves, offset by -nanmin per channel
  float dmax[3]; // nanmax(density_curves) per channel, post-normalization
  const float (*channel_density)[3]; // [SF_N_WAVELENGTHS][3], per-dye spectral absorption
  const float *base_density; // [SF_N_WAVELENGTHS], film-base + fog spectral density
  const float *spectral_valid; // [SF_N_WAVELENGTHS], 1 where channel_density/base_density were measured, 0 at NaN-masked edges
  float couplers_matrix[3][3]; // resolved DIR-coupler gamma matrix [donor][receiver], amount=1 baked in
} dt_sf_film_t;

typedef struct dt_sf_paper_t
{
  const char *stock;
  const char *display_name;
  int viewing_illuminant; // index into sf_view_illuminants
  const float (*sensitivity)[3]; // [SF_N_WAVELENGTHS][3], 10^log_sensitivity, unadapted (paper receives density input, not RGB)
  const float (*channel_density)[3]; // [SF_N_WAVELENGTHS][3]
  const float *base_density; // [SF_N_WAVELENGTHS]
  const float *spectral_valid; // [SF_N_WAVELENGTHS]
  float cdfs_centers[3][3]; // (channel, sublayer)
  float cdfs_amplitudes[3][3];
  float cdfs_sigmas[3][3];
} dt_sf_paper_t;



